import android.content.*;import com.tencent.shadow.core.runtime.*;import com.tencent.shadow.core.runtime.container.*;import com.tencent.shadow.core.loader.delegates.*;public class ContextHarness{public static void main(String[]a)throws Exception{Context plugin=new Context(){public Context getApplicationContext(){return this;}};PluginContainerActivity activity=new PluginContainerActivity();Context host=activity.getApplicationContext();ShadowActivityDelegate d=new ShadowActivityDelegate();activity.set(d);if(activity.getApplicationContext()!=host)throw new AssertionError("pre-injection fallback changed");d.inject(plugin);if(!(activity instanceof android.app.Activity)||activity.getApplicationContext()!=plugin)throw new AssertionError("Activity base identity/application mismatch");ShadowService service=new ShadowService(plugin);service.setHostContextAsBase(host);if(service.received.getApplicationContext()!=plugin||!service.received.facility().equals(host.facility()))throw new AssertionError();ShadowService same=new ShadowService(plugin);same.setHostContextAsBase(plugin);if(same.received!=plugin)throw new AssertionError("unneeded wrapper");if(host.getApplicationContext()!=host)throw new AssertionError("host global app changed");System.out.println("PASS actual bytecode patch: Activity identity retained, application exposed after injection but before attach; service attach receives plugin Application, facilities retained, host unchanged");}}